WITH inventory_by_store AS (SELECT store_id, MIN(last_restock) AS first_last_restock, AVG(quantity) AS avg_quantity FROM inventory GROUP BY store_id) SELECT stores.id, stores.city, stores.sqft, inventory_by_store.first_last_restock, inventory_by_store.avg_quantity FROM stores INNER JOIN inventory_by_store ON stores.id = inventory_by_store.store_id WHERE inventory_by_store.avg_quantity > 140 ORDER BY first_last_restock, id LIMIT 10;
